// Create a new resolver context
struct ub_ctx* ctx = ub_ctx_create();
// Caller must check for NULL; here we bail to keep pool clean
if (!ctx) { FUZZ_BAIL(); }
// Track context state for other stubs
FUZZ_SET_ATTR_INT(ctx, "finalized", 0);
FUZZ_SET_ATTR_INT(ctx, "async_outstanding", 0);
FUZZ_SET_ATTR_INT(ctx, "has_forwarders", 0);
FUZZ_SET_ATTR_INT(ctx, "tls_enabled", 0);
// Validation: ensures non-null ctx is produced; attributes initialized.

// Destroy resolver context; after this, ctx must not be used
ub_ctx_delete(ctx);
// Do not return ctx as an output to drop it from the pool
// Validation: releases resources and avoids use-after-free by not returning ctx.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
// opt must include trailing ':'
std::string opt = FUZZ_PARAM_STR();
if (opt.empty() || opt.back() != ':') opt.push_back(':');
std::string val = FUZZ_PARAM_STR();
(void)ub_ctx_set_option(ctx, opt.c_str(), val.c_str());
// Keep ctx in pool
// Validation: enforces pre-finalization and correct option format (trailing colon).

// Retrieve option; opt must exclude trailing ':'
std::string opt = FUZZ_PARAM_STR();
// strip one trailing ':' if present
if (!opt.empty() && opt.back() == ':') opt.pop_back();
if (opt.empty()) opt = "x"; // still valid API-wise; likely returns error
char* out = NULL;
int r = ub_ctx_get_option(ctx, opt.c_str(), &out);
if (r == 0 && out) { free(out); out = NULL; }
else if (out) { free(out); out = NULL; }
// Keep ctx in pool
// Validation: ensures output buffer is freed on success and error paths.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
const char* fname = FUZZ_PARAM_FILENAME();
(void)ub_ctx_config(ctx, fname);
// Keep ctx in pool
// Validation: enforces pre-finalization; uses fuzzer-provided filename.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
// Randomly choose to set or disable forwarding
int toggle = (int)(*FUZZ_PARAM(unsigned int) % 2);
const char* addr = nullptr;
std::string addr_s;
if (toggle) { addr_s = FUZZ_PARAM_STR(); addr = addr_s.c_str(); }
int rc = ub_ctx_set_fwd(ctx, addr);
if (rc == 0) {
    FUZZ_SET_ATTR_INT(ctx, "has_forwarders", addr ? 1 : 0);
}
// Keep ctx in pool
// Validation: enforces pre-finalization; tracks whether forwarders are configured.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
int tls = (int)(*FUZZ_PARAM(unsigned int) % 2);
int rc = ub_ctx_set_tls(ctx, tls);
if (rc == 0) { FUZZ_SET_ATTR_INT(ctx, "tls_enabled", tls ? 1 : 0); }
// Keep ctx in pool
// Validation: enforces pre-finalization; toggles and records TLS setting.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
std::string zone = FUZZ_PARAM_STR();
int add_or_remove = (int)(*FUZZ_PARAM(unsigned int) % 2);
const char* addr = nullptr;
std::string addr_s;
if (add_or_remove) { addr_s = FUZZ_PARAM_STR(); addr = addr_s.c_str(); }
int isprime = (int)(*FUZZ_PARAM(unsigned int) % 2);
(void)ub_ctx_set_stub(ctx, zone.c_str(), addr, isprime);
// Keep ctx in pool
// Validation: enforces pre-finalization; exercises both add and remove paths.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
int use_default = (int)(*FUZZ_PARAM(unsigned int) % 2);
const char* fname = use_default ? NULL : FUZZ_PARAM_FILENAME();
(void)ub_ctx_resolvconf(ctx, fname);
// Keep ctx in pool
// Validation: enforces pre-finalization and tests both default and custom path.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
int use_default = (int)(*FUZZ_PARAM(unsigned int) % 2);
const char* fname = use_default ? NULL : FUZZ_PARAM_FILENAME();
(void)ub_ctx_hosts(ctx, fname);
// Keep ctx in pool
// Validation: enforces pre-finalization; uses default or custom hosts file.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
std::string ta = FUZZ_PARAM_STR();
(void)ub_ctx_add_ta(ctx, ta.c_str());
// Keep ctx in pool
// Validation: enforces pre-finalization; passes single-line RR string data.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
const char* fname = FUZZ_PARAM_FILENAME();
(void)ub_ctx_add_ta_file(ctx, fname);
// Keep ctx in pool
// Validation: enforces pre-finalization; uses fuzzer-provided file path.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
const char* fname = FUZZ_PARAM_FILENAME();
(void)ub_ctx_add_ta_autr(ctx, fname);
// Keep ctx in pool
// Validation: enforces pre-finalization; exercises RFC5011 TA management path.

// Must be called before first resolve; enforce via attribute
if (FUZZ_GET_ATTR_INT(ctx, "finalized")) { FUZZ_BAIL(); }
const char* fname = FUZZ_PARAM_FILENAME();
(void)ub_ctx_trustedkeys(ctx, fname);
// Keep ctx in pool
// Validation: enforces pre-finalization; uses BIND-style trusted-keys file path.

// Set debug/error output stream. Use NULL to safely disable output.
void* out = NULL; // conceptual FILE*
(void)ub_ctx_debugout(ctx, out);
// Keep ctx in pool
// Validation: uses supported NULL stream; avoids invalid FILE* construction.

// Set verbosity level 0..3
int d = (int)(*FUZZ_PARAM(unsigned int) % 4);
(void)ub_ctx_debuglevel(ctx, d);
// Keep ctx in pool
// Validation: constrains level to documented range.

// Configure async mode: thread or process
int dothread = (int)(*FUZZ_PARAM(unsigned int) % 2);
(void)ub_ctx_async(ctx, dothread);
// Keep ctx in pool
// Validation: exercises both thread and process modes without side effects.

// Non-blocking poll for ready results (prefer fd-based readiness in real code)
(void)ub_poll(ctx);
// Keep ctx in pool
// Validation: single call avoids spinning; accepts any return value.

// Avoid potential blocking if there are outstanding async queries; bail if so
int outstanding = FUZZ_GET_ATTR_INT(ctx, "async_outstanding");
if (outstanding > 0) { FUZZ_BAIL(); }
(void)ub_wait(ctx);
// Keep ctx in pool
// Validation: guards against blocking by checking tracked outstanding count (0 by default).

// Obtain the context file descriptor; -1 indicates error
int fd = ub_fd(ctx);
(void)fd;
// Keep ctx in pool
// Validation: calls API and preserves ctx; no blocking or resource leaks.

// Process pending results/callbacks once; should be called when fd is readable
// We avoid tight loops here; a single call is sufficient for coverage
(void)ub_process(ctx);
// Keep ctx available for subsequent operations
// Validation: single non-blocking processing step; no assumptions about return value.

// Start an asynchronous resolve; this finalizes the context configuration
// Generate a (possibly non-DNS) name; API accepts any NUL-terminated string
std::string name = FUZZ_PARAM_STR();
int rrtype = (int)(*FUZZ_PARAM(unsigned int));
int rrclass = (int)(*FUZZ_PARAM(unsigned int));

// Prepare callback: free result if non-NULL to avoid leaks
ub_callback_type cb = +[](void* mydata, int err, struct ub_result* result){
    (void)mydata;
    (void)err;
    if (result) {
        ub_resolve_free(result);
    }
};

// mydata can be NULL; request an async_id so we can attempt cancellation later
int async_id = 0;
int rc = ub_resolve_async(ctx, name.c_str(), rrtype, rrclass, NULL, cb, &async_id);
// The context becomes finalized regardless of success
FUZZ_SET_ATTR_INT(ctx, "finalized", 1);
if (rc == 0) {
    // Track an outstanding query and remember its id
    int outstanding = FUZZ_GET_ATTR_INT(ctx, "async_outstanding");
    FUZZ_SET_ATTR_INT(ctx, "async_outstanding", outstanding + 1);
    FUZZ_SET_ATTR_INT(ctx, "last_async_id", async_id);
} else {
    // Submission failed; no outstanding query should be counted
}
// Keep ctx for downstream stubs
// Validation: callback safely frees results; attributes track finalization and outstanding count.

// Cancel a previously submitted async query
int outstanding = FUZZ_GET_ATTR_INT(ctx, "async_outstanding");
if (outstanding <= 0) { FUZZ_BAIL(); }
int async_id = FUZZ_GET_ATTR_INT(ctx, "last_async_id");
// If we somehow do not have an id recorded, bail to avoid meaningless call
if (async_id == 0) { FUZZ_BAIL(); }
int rc = ub_cancel(ctx, async_id);
if (rc == 0) {
    // On success, the callback will not be invoked; decrement outstanding
    FUZZ_SET_ATTR_INT(ctx, "async_outstanding", outstanding - 1);
}
// Keep ctx in the pool
// Validation: ensures we only attempt cancel when an id was recorded; updates counters on success.

// Free a result obtained from ub_resolve() or async callback
ub_resolve_free(result);
// Do not return 'result' to the pool to avoid use-after-free
// Validation: releases memory exactly once by dropping from outputs.

// Translate a random libunbound-style error code to text
int err = (int)(*FUZZ_PARAM(int));
const char* s = ub_strerror(err);
(void)s;
// Validation: returned pointer is static; we do not free or modify it.

// Print local zones to the configured debug stream; this finalizes the context
(void)ub_ctx_print_local_zones(ctx);
FUZZ_SET_ATTR_INT(ctx, "finalized", 1);
// Keep ctx in pool
// Validation: records finalization post-call.

// Add or update a local authority zone; call finalizes the context
std::string zone_name = FUZZ_PARAM_STR();
std::string zone_type = FUZZ_PARAM_STR();
(void)ub_ctx_zone_add(ctx, zone_name.c_str(), zone_type.c_str());
FUZZ_SET_ATTR_INT(ctx, "finalized", 1);
// Keep ctx for subsequent operations
// Validation: enforces finalization tracking.

// Remove a local authority zone; call finalizes the context
std::string zone_name = FUZZ_PARAM_STR();
(void)ub_ctx_zone_remove(ctx, zone_name.c_str());
FUZZ_SET_ATTR_INT(ctx, "finalized", 1);
// Keep ctx for further use
// Validation: tracks finalization post-call.

// Add local authority data RR; call finalizes the context
std::string rr = FUZZ_PARAM_STR();
(void)ub_ctx_data_add(ctx, rr.c_str());
FUZZ_SET_ATTR_INT(ctx, "finalized", 1);
// Keep ctx
// Validation: finalization flag updated.

// Remove local authority data for a given name; call finalizes the context
std::string name = FUZZ_PARAM_STR();
(void)ub_ctx_data_remove(ctx, name.c_str());
FUZZ_SET_ATTR_INT(ctx, "finalized", 1);
// Keep ctx
// Validation: finalization tracked.

// Obtain static version string
const char* v = ub_version();
(void)v;
// Validation: returned pointer is static; we do not free or modify it.

// Produce a ub_result* by performing a synchronous resolve on an existing context
// Note: ub_resolve() finalizes the context, after which setters will bail in other stubs.
// We keep ctx alive and return the result to the pool; caller must later use ub_resolve_free(result).

// Generate a domain name (any NUL-terminated string is accepted by the API)
std::string name = FUZZ_PARAM_STR();
// Generate rrtype and rrclass in host byte order; use full int range
int rrtype = (int)(*FUZZ_PARAM(unsigned int));
int rrclass = (int)(*FUZZ_PARAM(unsigned int));

struct ub_result* tmp = nullptr;
int rc = ub_resolve(ctx, name.c_str(), rrtype, rrclass, &tmp);
// Context becomes finalized regardless of rc
FUZZ_SET_ATTR_INT(ctx, "finalized", 1);

// On success, tmp must be non-NULL per API; on error it may be NULL
if (rc != 0 || tmp == nullptr) {
    // Nothing to free here (tmp is NULL or unspecified); bail to avoid returning NULL
    FUZZ_BAIL();
}

// Hand the successful result to the fuzzer runtime as output
struct ub_result* result = tmp;

// Validation: ensures ctx is tracked as finalized and only non-null results are emitted; result ownership passes to fuzzer pool for ub_resolve_free later.

