INT_VALUES = [
    "0", "1", "2", "3", "5", "10", "60", "300", "600", "900", "1024", "2048",
    "4096", "65535"
]

# sizes can be plain integers or integers with units (k, m)
SIZE_VALUES = [
    "0", "4096", "8192", "1048576", "4k", "16k", "64k", "1m", "8m", "64m"
